`timescale 1ns/1ps

// Generated by tools/gen_font.py. Do not edit by hand.
// 5x7 glyphs packed as seven 5-bit rows, row 0 in the most significant
// bits, so a row is selected with glyph[5*(6-row) +: 5].
module char_rom (
    input      [7:0] ascii,
    input      [2:0] row,
    output reg [4:0] bits
